import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007L;
    static long N, K;
    static long[][] Power = new long[65][1]; // actually only Power[0..64] as long[]
    static long[][] Res = new long[35][35];
    static long[][][][] S = new long[65][35][35][35];
    static long[][][][] A = new long[65][35][35][35];
    static long[][][][] P = new long[65][35][35][35];
    static long[][] Aux = new long[35][35];

    // Helper: copy matrix from Y to X (both n x n)
    static void copy(long[][] X, long[][] Y, int n) {
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                X[i][j] = Y[i][j];
    }

    // Inline add modulo (simulated)
    static void add(long[] x, long y) {
        x[0] += y;
        if (x[0] >= MOD) x[0] -= MOD;
    }

    // Matrix multiply: Z = X * Y, dimensions n x m * m x p -> n x p
    static void mul(long[][] X, long[][] Y, long[][] Z, int n, int m, int p) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < p; j++) {
                Z[i][j] = 0;
                for (int k = 0; k < m; k++) {
                    // Use add with temporary variable to avoid boxing
                    long prod = (X[i][k] * Y[k][j]) % MOD;
                    Z[i][j] += prod;
                    if (Z[i][j] >= MOD) Z[i][j] -= MOD;
                }
            }
        }
    }

    static void precalcA() {
        // Build level 0 matrices
        for (int x = 0; x < (int)K; x++) {
            for (int i = 0; i < K + 1; i++)
                A[0][x][i][i] = 1;
            for (int j = 0; j < K + 1; j++)
                A[0][x][j][x] = 1;
        }
        // Copy A[0][0] to P[0][0]
        copy(P[0][0], A[0][0], (int)K + 1);
        copy(S[0][(int)K - 1], A[0][(int)K - 1], (int)K + 1);
        for (int x = 1; x < K; x++) {
            mul(P[0][x - 1], A[0][x], P[0][x], (int)K + 1, (int)K + 1, (int)K + 1);
        }
        for (int x = (int)K - 2; x >= 0; x--) {
            mul(A[0][x], S[0][x + 1], S[0][x], (int)K + 1, (int)K + 1, (int)K + 1);
        }
        int cnt = 1;
        for (long m = K; m <= N; m *= K, cnt++) {
            for (int x = 0; x < K; x++) {
                if (x > 0) {
                    copy(A[cnt][x], S[cnt - 1][x], (int)K + 1);
                    mul(A[cnt][x], P[cnt - 1][x - 1], Aux, (int)K + 1, (int)K + 1, (int)K + 1);
                    copy(A[cnt][x], Aux, (int)K + 1);
                } else {
                    copy(A[cnt][x], S[cnt - 1][x], (int)K + 1);
                }
            }
            copy(P[cnt][0], A[cnt][0], (int)K + 1);
            copy(S[cnt][(int)K - 1], A[cnt][(int)K - 1], (int)K + 1);
            for (int x = 1; x < K; x++) {
                mul(P[cnt][x - 1], A[cnt][x], P[cnt][x], (int)K + 1, (int)K + 1, (int)K + 1);
            }
            for (int x = (int)K - 2; x >= 0; x--) {
                mul(A[cnt][x], S[cnt][x + 1], S[cnt][x], (int)K + 1, (int)K + 1, (int)K + 1);
            }
            if (m > N / K) break;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        N = scanner.nextLong();
        K = scanner.nextLong();
        scanner.close();

        // Prepare Power array (as long array)
        long[] powerArr = new long[65];
        powerArr[0] = 1;
        int i = 1;
        while (powerArr[i - 1] <= N / K) {
            powerArr[i] = powerArr[i - 1] * K;
            i++;
        }
        int ind = i - 1;

        precalcA();

        long init = N;
        int ind2 = 0;
        // Initialize Res as identity? Actually original had Res[0][K]=1 and rest zero.
        for (int a = 0; a < 35; a++)
            for (int b = 0; b < 35; b++)
                Res[a][b] = 0;
        Res[0][(int)K] = 1;

        for (int i2 = ind; i2 >= 0; i2--) {
            while (powerArr[i2] <= init) {
                mul(Res, A[i2][ind2], Aux, (int)K + 1, (int)K + 1, (int)K + 1);
                copy(Res, Aux, (int)K + 1);
                ind2++;
                if (ind2 == K) ind2 = 0;
                init -= powerArr[i2];
            }
        }

        long ans = 0;
        for (int j = 0; j <= K; j++) {
            ans += Res[0][j];
            if (ans >= MOD) ans -= MOD;
        }
        System.out.println(ans);
    }
}
